MultiLanguageSpellData['mx'][84410] = {name = "[q3]Equipo de retirada de seguro", additional_info = "Hechizo de 1.5 seg 5\nHerramientas: Microajustador giromático\nComponentes:\nBarra de obsidium (10), Puñado de tornillos de obsidium (10)\n[q3]Equipo de retirada de seguro\nNecesitas ser de nivel 80\n[q2]Uso: Elimina el mecanismo de seguridad de un arco o arma de fuego, lo que aumenta su celeridad a distancia 88 p.\n\n Al usar este equipo, el arco o arma de fuego se ligará."}
MultiLanguageSpellData['mx'][84411] = {name = "[q3]Pistola de descarga de gran potencia", additional_info = "Hechizo de 4 seg 5\nHerramientas: Martillo de herrero , Microajustador giromático\nComponentes:\nBarra de obsidium (10), Puñado de tornillos de obsidium (8), Éter electrificado (4)\n[q3]Pistola de descarga de gran potencia\nSe liga al usarlo\nRequiereIngeniería\n(450)\n[q2]Uso: Dispara varios tornillos cargados a un enemigo que infligen 10180 p. de daño e interrumpen brevemente el lanzamiento. Consume un puñado de tornillos de obsidium cada vez que se dispara. (2 Min Reutilización)\n[q]\"Casi tan complicada de hacer que funcione como de fabricarla.\""}
MultiLanguageSpellData['mx'][84412] = {name = "[q3]Destruyemundos personal", additional_info = "Hechizo de 1.5 seg 5\nHerramientas: Pistola de descarga de gran potencia , Martillo de herrero\nComponentes:\nBarra de obsidium (10), Puñado de tornillos de obsidium (8), Éter electrificado (8)\n[q3]Destruyemundos personal\n[q2]Uso: Te enseña a invocar este compañero.\n[q2]Haz clic con el botón derecho del ratón para invocar y retirar a tu destruyemundos personal."}
MultiLanguageSpellData['mx'][84413] = {name = "[q3]Compañero mecánico sin armas", additional_info = "Hechizo de 1.5 seg 5\nHerramientas: Pistola de descarga de gran potencia , Llave de tuerca arcoluz\nComponentes:\nBarra de obsidium (12), Puñado de tornillos de obsidium (4), Éter electrificado (8), Jaspe (2)\n[q3]Compañero mecánico sin armas\n[q2]Uso: Te enseña a invocar este compañero.\n[q2]Haz clic con el botón derecho del ratón para invocar y retirar a tu compañero mecánico sin armas."}
MultiLanguageSpellData['mx'][84415] = {name = "[q3]Caja de aparejos Maestro del Cebo", additional_info = "Hechizo de 5 seg 5\nHerramientas: Martillo de herrero , Pistola de descarga de gran potencia\nComponentes:\nBarra de elementium (20), Puñado de tornillos de obsidium (4)\n[q3]Caja de aparejos Maestro del Cebo\nSe liga al equiparlo\nCaja de aparejos de 36 casillas"}
MultiLanguageSpellData['mx'][84416] = {name = "[q3]Caja de herramientas de elementium", additional_info = "Hechizo de 5 seg 5\nHerramientas: Martillo de herrero\nComponentes:\nBarra de elementium (15), Tierra volátil (12)\n[q3]Caja de herramientas de elementium\nSe liga al equiparlo\nBolsa de ingeniería de 36 casillas\n[q]\"Posiblemente la mejor caja de herramientas jamás hecha, adornada con incrustaciones de oro.\""}
MultiLanguageSpellData['mx'][84417] = {name = "[q3]Truenopalo volátil", additional_info = "Hechizo de 1.5 seg 5\nHerramientas: Martillo de herrero , Microajustador giromático\nComponentes:\nÉter electrificado (2), Barra de elementium endurecido (5), Fuego volátil (6)\n[q3]Truenopalo volátil\nSe liga al equiparlo\nA distancia Arma de fuego\n1,917 - 3,562 p. de daño Velocidad 2.80\n(978.39 p. de daño por segundo)\n+268 agilidad\n+401 aguante\n[q2]Aumenta tu índice de golpe crítico + 178 p.\n[q2]Aumenta tu índice de maestría + 178 p.\nDurabilidad 100 / 100\nNecesitas ser de nivel 83"}
MultiLanguageSpellData['mx'][84418] = {name = "[q3]Dragonizo de elementium", additional_info = "Hechizo de 1.5 seg 5\nHerramientas: Martillo de herrero , Pistola de descarga de gran potencia\nComponentes:\nPuñado de tornillos de obsidium (2), Éter electrificado (8), Barra de elementium (16), Paño de seda de ascuas (20)\n[q3]Dragonizo de elementium\nSe liga al equiparlo\nÚnico-EquipadoAbalorio\n[q2]Aumenta tu índice de maestría + 252 p.\nNecesitas ser de nivel 80\nRequiereIngeniería\n(475)\n[q2]Uso: Activa tu dragonizo de elementium para que luche por ti durante 1 min. (5 Min Reutilización)"}
MultiLanguageSpellData['mx'][84419] = {name = "Grito desafiante", additional_info = "{Instante} {10 seg de reutilización}\n[q]Provoca al objetivo para que te ataque, pero no tiene efecto si ya te está atacando."}
MultiLanguageSpellData['mx'][84420] = {name = "[q3]Taladro de garganta bien afinado", additional_info = "Hechizo de 1.5 seg 5\nHerramientas: Martillo de herrero , Llave de tuerca arcoluz\nComponentes:\nBarra de obsidium (4), Éter electrificado (2), Barra de elementium endurecido (5)\n[q3]Taladro de garganta bien afinado\nSe liga al equiparlo\nA distancia Ballesta\n1,986 - 3,689 p. de daño Velocidad 2.90\n(978.45 p. de daño por segundo)\n+268 agilidad\n+402 aguante\n[q2]Aumenta tu índice de golpe crítico + 157 p.\n[q2]Aumenta tu índice de celeridad + 191 p.\nDurabilidad 75 / 75\nNecesitas ser de nivel 83"}
MultiLanguageSpellData['mx'][84421] = {name = "[q3]Despojador a distancia", additional_info = "Hechizo de 5 seg 5\nHerramientas: Martillo de herrero , Llave de tuerca arcoluz\nComponentes:\nBarra de elementium endurecido (5), Éter electrificado (5)\n[q3]Despojador a distancia\nSe liga al usarlo\nJuguete\nRequiereIngeniería\n(125)\n[q2]Uso: Obtiene el botín de un cadáver cercano. (3 Seg Reutilización)"}
MultiLanguageSpellData['mx'][84424] = {name = "Campo de invisibilidad", additional_info = "Hechizo de 5 seg\nRequiere Cinturón\nHerramientas: Llave de tuerca arcoluz\nComponentes:\nKit de manitas\n[q]Añade de forma permanente miles de espejitos a tu cinturón, lo que te permite intentar volverte invisible cuando no estás en combate. Solo se puede activar una vez cada 3 min.\n\n Solo se puede usar con tu propio cinturón, y hacerlo provoca que se ligue. Operarlo requiere una habilidad en ingeniería de al menos 450 p."}
MultiLanguageSpellData['mx'][84425] = {name = "Asesino de cartón", additional_info = "Hechizo de 5 seg\nRequiere Cinturón\nHerramientas: Llave de tuerca arcoluz\nComponentes:\nKit de manitas\n[q]Añade de forma permanente un artilugio diminuto a tu cinturón, lo que te permite crear un asesino de cartón al que atacarán tus enemigos. Dura 15 s. Se puede utilizar una vez cada 5 min.\n\n Solo se puede usar con tu propio cinturón y hacerlo provoca que se ligue. Operarlo requiere una habilidad en ingeniería de al menos 450 p."}
MultiLanguageSpellData['mx'][84426] = {name = "Aliento vil", additional_info = "Alcance de ataques cuerpo a cuerpo\nHechizo de 2.5 seg\n[q]Inflige daño de Fuego a los enemigos que se encuentran en un cono frente al taumaturgo."}
MultiLanguageSpellData['mx'][84427] = {name = "Escudo de plasma con toma de tierra", additional_info = "Hechizo de 5 seg\nRequiere Cinturón\nHerramientas: Llave de tuerca arcoluz\nComponentes:\nKit de manitas\n[q]Añade de forma permanente unos generadores de plasma con toma de tierra a tu cinturón, lo que te permite activar un poderoso escudo que absorbe ( 14400 * 4.5) - ( 17600 * 4.5) p. de daño. Se puede usar una vez cada 5 minutos.\n\n Solo se puede usar con tu propio cinturón, y hacerlo provocará que se ligue al alma. Operarlo requiere una habilidad en ingeniería de al menos 450 p."}
MultiLanguageSpellData['mx'][84428] = {name = "[q3]Mira de rayos X gnómica", additional_info = "Hechizo de 1.5 seg 4\nHerramientas: Martillo de herrero , Microajustador giromático\nComponentes:\nBarra de elementium endurecido (2), Esmeralda onírica (2)\n[q3]Mira de rayos X gnómica\nNecesitas ser de nivel 80\n[q2]Uso: Añade una mira permanente a un arco o arma de fuego, lo que aumenta en ocasiones el poder de ataque a distancia 800 p. durante 10 s al infligir daño con ataques a distancia.\n\n Al añadir la mira a un arma a distancia se liga."}
MultiLanguageSpellData['mx'][84429] = {name = "Barbacoa goblin", additional_info = "Hechizo de 1.5 seg\nHerramientas: Pistola de descarga de gran potencia , Llave de tuerca arcoluz\nComponentes:\nBarra de elementium (2), Carne fortalecida (2), Filete de lavesco (2)\nNecesitas ser de nivel 80\nRequiereCocina\n(475)\n[q2]Uso: ¡Saca una barbacoa para alimentar a todo tu grupo o banda!\n\n Restaura 67500 p. de salud y ( 7500 / 5 * 30) p. de maná durante 30 s. Si pasas al menos 10 s comiendo estarás bien alimentado y ganarás 60 p. de aguante y 60 p. de otra estadística útil durante 1 h."}
MultiLanguageSpellData['mx'][84430] = {name = "Cebo giratorio tratado con calor", additional_info = "Hechizo de 1.5 seg\nHerramientas: Llave de tuerca arcoluz , Microajustador giromático\nComponentes:\nPuñado de tornillos de obsidium , Barra de elementium (4), Fuego volátil\n(2)\nRequierePesca\n(250)\n[q2]Uso: Si se aplica a la caña de pescar aumenta Pesca 150 p. durante 15 minutos.\n[q]\"¡Funciona hasta en la lava!\""}
MultiLanguageSpellData['mx'][84431] = {name = "[q3]Machacapollos derrotado", additional_info = "Hechizo de 1.5 seg\nHerramientas: Martillo de herrero , Llave de tuerca arcoluz\nComponentes:\nBarra de elementium endurecido (12), Veraoro (2), Puñado de tornillos de obsidium (6), Éter electrificado (8), Orbe del caos\n[q3]Machacapollos derrotado\nSe liga al equiparlo\nA distancia Arco\n2,164 - 4,020 p. de daño Velocidad 2.80\n(1,104 p. de daño por segundo)\n+302 agilidad\n+454 aguante\n[q2]Aumenta tu índice de golpe crítico + 216 p.\n[q2]Aumenta tu índice de celeridad + 177 p.\nDurabilidad 100 / 100\nNecesitas ser de nivel 85"}
MultiLanguageSpellData['mx'][84432] = {name = "[q3]Culatazo 5000", additional_info = "Hechizo de 1.5 seg\nHerramientas: Martillo de herrero , Llave de tuerca arcoluz\nComponentes:\nBarra de elementium endurecido (9), Veraoro (3), Gatillo de pelo , Culata de nogal , Orbe del caos\n[q3]Culatazo 5000\nSe liga al equiparlo\nA distancia Arma de fuego\n2,164 - 4,020 p. de daño Velocidad 2.80\n(1,104 p. de daño por segundo)\n+282 agilidad\n+454 aguante\n[q2]Aumenta tu índice de golpe crítico + 207 p.\n[q2]Aumenta tu índice de celeridad + 176 p.\n\n[q0]Ranura roja\n[q0]Bono de ranura: + 10 agilidad\n\nDurabilidad 100 / 100\nNecesitas ser de nivel 85"}
