MultiLanguageSpellData['mx'][90451] = {name = "[q0]Ánfora kaldorei", additional_info = "Hechizo de 2 seg 5\n[q]Esta vasija esbelta con dos asas curvas se utilizó para mezclar o almacenar vino darnassiano. Incluso pasado todo este tiempo, aún se puede detectar un débil olor a jengibre de los residuos secos del fondo de la vasija.\n[q0]Ánfora kaldorei\nSe liga al recogerlo"}
MultiLanguageSpellData['mx'][90452] = {name = "[q0]Mandíbulas de tiburón antiguo", additional_info = "Hechizo de 2 seg 5\n[q]Los tiburones no tienen huesos de verdad, solo cartílago. Como sus hábitos alimenticios incluyen morder cosas con mucha fuerza, la pérdida de dientes es común. Por ello, los tiburones tienen varias filas de dientes que reemplazan constantemente durante su vida.\n[q0]Mandíbulas de tiburón antiguo\nSe liga al recogerlo"}
MultiLanguageSpellData['mx'][90453] = {name = "[q0]Horquilla de plata y malaquita", additional_info = "Hechizo de 2 seg 5\n[q]Grabado bajo el hueco para la piedra preciosa se puede leer \"A Theleste, en su 24 cumpleaños\".\n[q0]Horquilla de plata y malaquita\nSe liga al recogerlo"}
MultiLanguageSpellData['mx'][90454] = {name = "Item - Death Knight T11 Blood 2P Bonus", additional_info = "[q]Aumenta un 5% el daño infligido por tu facultad Golpe letal."}
MultiLanguageSpellData['mx'][90456] = {name = "Item - Death Knight T11 Blood 4P Bonus", additional_info = "[q]Aumenta un 50% la duración de tu facultad Entereza ligada al hielo."}
MultiLanguageSpellData['mx'][90457] = {name = "Item - Death Knight T11 DPS 2P Bonus", additional_info = "[q]Aumenta un 5% la probabilidad de golpe crítico de tus facultades Espiral de la muerte y Golpe de Escarcha."}
MultiLanguageSpellData['mx'][90458] = {name = "[q0]Caja de música delicada", additional_info = "Hechizo de 2 seg 5\n[q]Se trata de una caja de sándalo con un pequeño elfo mecánico y un sable de la noche en el interior. Aunque el sinuoso mecanismo ya no funciona, puedes imaginar cómo los dos bailaban juntos mientras sonaba la música. Grabado en el fondo: \"A mi querida Theleste\".\n[q0]Caja de música delicada\nSe liga al recogerlo"}
MultiLanguageSpellData['mx'][90459] = {name = "Item - Death Knight T11 DPS 4P Bonus", additional_info = "[q]Cada vez que obtienes una runa de muerte o activas el talento Máquina de matar, también obtienes un 1% de poder de ataque aumentado durante 30 s. Se acumula hasta 3 veces."}
MultiLanguageSpellData['mx'][90460] = {name = "Item - Rogue T11 2P Bonus", additional_info = "[q]Aumenta un 5% la probabilidad de golpe crítico de tus facultades Puñalada, Mutilar y Golpe siniestro."}
