MultiLanguageSpellData['mx'][90852] = {name = "Llamar relámpagos", additional_info = "Alcance de 30 m\nInstante\n[q]Inflige 11700 to 12300 p. de daño de Naturaleza."}
MultiLanguageSpellData['mx'][90853] = {name = "[q0]Argolla con campanas doradas", additional_info = "Hechizo de 2 seg 5\n[q]Este aro fino de metal violeta está adornado con diecisiete campanillas y abalorios amarillos más grandes de vidrio soplado. Podría haberlo llevado una bailarina o una joven de alta cuna.\n[q0]Argolla con campanas doradas\nSe liga al recogerlo"}
MultiLanguageSpellData['mx'][90854] = {name = "Visionario", additional_info = "Instante\n[q]Poder con hechizos aumentado 21 p. durante 15 s. Se acumula hasta 6 veces."}
MultiLanguageSpellData['mx'][90855] = {name = "Item - Stacking Spell Power", additional_info = "[q]Tus hechizos otorgan 21 p. de poder con hechizos durante 15 s, lo que se acumula hasta 6 veces."}
MultiLanguageSpellData['mx'][90860] = {name = "[q0]Arpa tallada en madera exótica", additional_info = "Hechizo de 2 seg 5\n[q]Esta pequeña arpa se sujetaba con una mano, como una lira. Tiene una profunda caja de resonancia de madera con varias cuerdas fijadas a una barra que gira. Vale para tocar música, pero parece que solo produce notas tristes y melancólicas.\n[q0]Arpa tallada en madera exótica\nSe liga al recogerlo"}
MultiLanguageSpellData['mx'][90861] = {name = "[q0]Pisapapeles plateado extraño", additional_info = "Hechizo de 2 seg 5\n[q]Si este objeto no se utilizaba como pisapapeles draenei, entonces no tengo ni idea de su función. Parece ser una gota de mercurio petrificado con un lado plano para poder apoyarlo en un escritorio.\n[q0]Pisapapeles plateado extraño\nSe liga al recogerlo"}
MultiLanguageSpellData['mx'][90864] = {name = "[q0]Cetro de Nathrezim", additional_info = "Hechizo de 2 seg 5\n[q]Los Nathrezim, también conocidos como señores del terror, actúan como agentes de inteligencia e interrogadores de la Legión Ardiente. Aunque se trata de enemigos poderosos en el campo de batalla, prefieren enfrentar a naciones entre ellas a través de la manipulación y la astucia.\n[q0]Cetro de Nathrezim\nSe liga al recogerlo"}
