MultiLanguageSpellData['mx'][91008] = {name = "[q0]Chaira", additional_info = "Hechizo de 2 seg 5\n[q]Las chairas son cuchillos grandes y rectos con un solo filo y una empuñadura simple que llevaban muchos guerreros vrykul como arma lateral. Un estilo de lucha común entre los guerreros consiste en tener el hacha en la mano derecha y la chaira en la izquierda.\n[q0]Chaira\nSe liga al recogerlo"}
MultiLanguageSpellData['mx'][91009] = {name = "Fuerza renegada", additional_info = "Instante\n[q]Colma al objetivo con la fuerza de los Defias. Aumenta el daño físico un 200%, reduce el daño recibido de los hechizos y facultades de área de efecto un 90% y aumenta la salud un 300%."}
