MultiLanguageSpellData['mx'][91012] = {name = "[q0]Asediador de sílex", additional_info = "Hechizo de 2 seg 5\n[q]Este sencillo asediador de sílex se utilizaba para encender fuego. La vara está tallada como la cabeza de un dragón, mientras que la hoja plana de metal está decorada para que parezca un pez estilizado.\n[q0]Asediador de sílex\nSe liga al recogerlo"}
MultiLanguageSpellData['mx'][91013] = {name = "Temporraíz", additional_info = "Instante\n[q]Aumenta tu poder con hechizos 1926 p. durante 15 s."}
MultiLanguageSpellData['mx'][91014] = {name = "[q0]Fíbula de capa dentuda", additional_info = "Hechizo de 2 seg 5\n[q]Este broche se debe haber utilizado para atar una gran capa vrykul sobre los hombros. Fijados a la fíbula cruciforme son dos grandes dientes desgastados, muy probablemente de un protodraco camino de la vejez. No queda claro si el propietario del broche sentía alguna afinidad por el viejo draco o si esa criatura fue lo único que era capaz de derrotar.\n[q0]Fíbula de capa dentuda\nSe liga al recogerlo"}
MultiLanguageSpellData['mx'][91017] = {name = "Ola de sanación", additional_info = "{145 p. de maná} {Alcance de 40 m}\nHechizo de 3 seg\n[q]Invoca la magia de Naturaleza para sanar a un aliado."}
MultiLanguageSpellData['mx'][91018] = {name = "Sanación en cadena", additional_info = "Alcance de 40 m\nHechizo de 2.5 seg\n[q]Imbuye a un aliado herido con energía de sanación que se extiende a otro aliado cercano. El hechizo afecta hasta a 3 objetivos, pero la energía de sanación disminuye un 50% en cada objetivo sucesivo."}
