MultiLanguageSpellData['mx'][91080] = {name = "Item - Proc Wandering DoT", additional_info = "[q]Tus hechizos dañinos tienen una probabilidad de infectar a tu víctima con Fuego fatuo vengativo, lo que inflige 542 p. de daño cada 3 s. Además, cada vez que el Fuego fatuo vengativo inflige daño, tiene un 10% de probabilidad de transmitirse a un enemigo cercano aleatorio.\n(Probabilidad de que accione: 10%, 1.667m de reutilización)"}
