MultiLanguageSpellData['mx'][91205] = {name = "Haces Alfa", additional_info = "Rango ilimitado\nInstante\n[q]Inflige 0 p. de daño de las Sombras cada 0.5 s durante hasta cancelación."}
MultiLanguageSpellData['mx'][91209] = {name = "[q0]Búcaro de sangre de jormungar", additional_info = "Hechizo de 2 seg 5\n[q]Esta botella de cristal contiene la sangre ácida y fría como el hielo de uno de los grandes gusanos jormungar de Rasganorte. De acuerdo con la leyenda, los nerubianos utilizaban los jormungar para cavar muchos de los pasajes y grutas subterráneas que formaban las grandes ciudades de Azjol-Nerub.\n[q0]Búcaro de sangre de jormungar\nSe liga al recogerlo"}
MultiLanguageSpellData['mx'][91211] = {name = "[q0]Banderín garabateado de visir", additional_info = "Hechizo de 2 seg 5\n[q]Este objeto extraño parece ser un trozo de un pergamino de proporciones inmensas. El material es un cruce entre papiro y cuero está cubierto de diagramas y escritura nerubiana en rojo y carmesí. \"Unhhh-tikk-a-shisss. Kka shir. Na-l bkah a-shisss. Kreesh kik ik ta. Sohk-a tik hiss a-k-k-k\".\n[q0]Banderín garabateado de visir\nSe liga al recogerlo"}
MultiLanguageSpellData['mx'][91212] = {name = "Oleada", additional_info = "Alcance de 45 m\n{Instante} {3 seg de reutilización}\n[q]Carga contra un enemigo, lo que inflige 10822 to 12577 p. de daño al objetivo y a cualquiera de sus aliados cercanos y los repele."}
MultiLanguageSpellData['mx'][91213] = {name = "Machaque", additional_info = "Instante\n[q]Inflige 19000 to 21000 p. de daño físico a los objetivos enemigos cercanos en un radio de 10 m."}
MultiLanguageSpellData['mx'][91214] = {name = "[q4]Bendición del dios antiguo", additional_info = "Hechizo de 2 seg 15\n[q]Pwhn'guul i ghawl'fwata ryiu wgah uul'gwan h'iwn guu'lal. Pwhn'guul i ghawl'fwata ryiu wgah uul'gwan h'iwn guu'lal. Pwhn'guul i ghawl'fwata ryiu wgah uul'gwan h'iwn guu'lal.\n[q4]Bendición del dios antiguo\nSe liga al recogerlo\nJuguete\n[q2]Uso: Recibe la Bendición del dios antiguo durante 20 s. (10 Min Reutilización)"}
MultiLanguageSpellData['mx'][91215] = {name = "[q4]Caja de puzles de Yogg-Saron", additional_info = "Hechizo de 2 seg 15\n[q]Esta pequeña caja tiene muchos paneles que se cambian, bisagras que se mueven y cierres escondidos. Pero no importa cómo los manipules, parece imposible abrir la caja para descubrir los contenidos de su interior. También es difícil simplemente intentarlo, porque el artefacto oscuro no deja de susurrarte: \"FUE culpa tuya. FUE culpa tuya. FUE culpa tuya. FUE culpa tuya\".\n[q4]Caja de puzles de Yogg-Saron\nSe liga al recogerlo\nJuguete\n[q2]Uso: Intenta en vano abrir la caja de puzles. (1 Min Reutilización)\n[q]\"Casi imposible de abrir.\""}
