MultiLanguageSpellData['mx'][91713] = {name = "Resguardo abisal", additional_info = "[q]Transforma tu Resguardo crepuscular en Resguardo abisal.\n\nResguardo abisal\n Absorbe [ 3942 + (Spell power * 0.807)] p. de daño. Dura 30 s. 30 s de tiempo de reutilización.\n\n Cuando absorbes daño, obtienes Protección abisal, que reduce todo el daño de esa escuela de magia un 15% durante 12 s."}
