MultiLanguageSpellData['mx'][103130] = {name = "Abisario: Escudo de las Sombras", additional_info = "[q]Otorga a tu abisario la facultad Escudo de las Sombras.\n\nEscudo de las Sombras Facultad especial 60 p. de energía Instantáneo Reutilización: 10 s Requires level 28 Reviste al abisario con energía de las Sombras que reduce el daño físico recibido un 60% durante 30 s.\n\n Cada vez que golpean al abisario, se desata una ola de daño de las Sombras que inflige 1115 p. de daño de las Sombras y reduce el poder de Escudo de las Sombras un 20%.\n\nLanzamiento automático:\n Se lanza al recibir ataques.\n\n(Clic derecho para activar)"}
MultiLanguageSpellData['mx'][103131] = {name = "Guardia vil: Lanzamiento de hachas", additional_info = "[q]Otorga a tu guardia vil la facultad Lanzamiento de hachas.\n\n El guardia vil lanza su hacha y aturde al objetivo durante 4 s."}
MultiLanguageSpellData['mx'][103133] = {name = "Diablillo: Huir", additional_info = "[q]Otorga a tu diablillo la facultad Huir.\n\nHuir Facultad especial 20 p. de energía Alcance de 40 m Instantáneo Reutilización: 20 s Requires level 33 Huye a la ubicación del amo. Huir elimina todos los efectos de aturdimiento y raíces."}
MultiLanguageSpellData['mx'][103134] = {name = "Guardia vil: Tormenta Vil", additional_info = "[q]Otorga a tu guardia vil la facultad Tormenta Vil.\n\nEl guardia vil golpea salvajemente con su arma a todos los objetivos cercanos en un radio de 8 m y les inflige un 100% de daño con arma cada 1 s durante 6 s.\n\n El guardia vil no puede utilizar otras facultades durante Tormenta Vil."}
MultiLanguageSpellData['mx'][103135] = {name = "Manáfago: Bloqueo de hechizo", additional_info = "[q]Otorga a tu manáfago la facultad Bloqueo de hechizo.\n\nBloqueo de hechizo Facultad especial 20 p. de energía Alcance de 40 m Instantáneo Reutilización: 24 s Requires level 50 Silencia al enemigo durante 3 s. Si se usa contra un objetivo que lanza hechizos, contrarrestará el lanzamiento de hechizos, lo que evita que lance hechizos de esa escuela de magia durante 6 s."}
