MultiLanguageSpellData['mx'][103139] = {name = "Súcubo: Seducción", additional_info = "[q]Otorga a tu súcubo la facultad Seducción.\n\nSeducción Facultad especial 20 p. de energía Alcance de 30 m 1.7 s para lanzar\n Requires level 20 Seduce al objetivo y le impide toda acción durante un máximo de 30 s. Todo daño infligido elimina el efecto. Solo funciona contra humanoides.\n\nLanzamiento automático:\n Se lanza contra objetivos que atacan, aturden, silencian o aterrorizan a su amo.\n\n(Clic derecho para activar)"}
MultiLanguageSpellData['mx'][103140] = {name = "Súcubo: Invisibilidad inferior", additional_info = "[q]Otorga a tu súcubo la facultad Invisibilidad inferior.\n\nInvisibilidad inferior Facultad especial 20 p. de energía\n Instantáneo\n Requires Warlock\n Requires level 32 Da al súcubo Invisibilidad inferior durante un máximo de 5 min. Este hechizo solo se puede usar cuando no estás en combate.\n\nLanzamiento automático:\n Se reaplica cuando el súcubo abandona el combate.\n\n(Clic derecho para activar)"}
