MultiLanguageSpellData['mx'][108279] = {name = "Tótem de Mente sosegada", additional_info = "6% del maná base\n{Instante} {1 min de reutilización}\n[q]Invoca un tótem de aire con 5 p. de salud a los pies del taumaturgo durante 6 s, lo que otorga inmunidad a los efectos de interrupción y silencio a los miembros de la banda en un radio de 30 m."}
MultiLanguageSpellData['mx'][108280] = {name = "Tótem de Marea de sanación", additional_info = "8% del maná base\n{Instante} {3 min de reutilización}\n[q]Invoca un tótem de agua con un [ Glifo de Vigor totémico : 15 / 10]% de la salud del taumaturgo a los pies de este durante 10 s. El tótem de Marea de sanación emite un pulso cada 2 s, lo que sana 4932 p. a los 5 (12 en estancias de 25 jugadores) miembros del grupo o banda más heridos en un radio de 40 m."}
MultiLanguageSpellData['mx'][108281] = {name = "Guía ancestral", additional_info = "[q0]Talento\n{Instante} {2 min de reutilización}\n[q]Al infligir daño directo o realizar sanación directa durante los próximos 10 s, un 40% de daño o un 60% de sanación de esa cantidad se copia como sanación para un máximo de 3 miembros heridos cercanos del grupo o banda."}
MultiLanguageSpellData['mx'][108282] = {name = "Conductividad", additional_info = "[q0]Talento\n[q]Cuando lanzas Ola de sanación, Ola de sanación superior, Oleada de sanación o Sanación en cadena, la duración de tu Lluvia de sanación aumenta 4.00 s.\n\n Cuando lanzas Descarga de relámpagos, Cadena de relámpagos, [ Explosión elemental : Explosión elemental ]Choque de tierra o Golpe de tormenta, la duración de tu Lluvia de sanación aumenta 4.00 s.\n\n Este efecto no puede hacer que Lluvia de sanación dure más de 40 s."}
MultiLanguageSpellData['mx'][108283] = {name = "Eco de los elementos", additional_info = "[q0]Talento\n[q]Cuando uno de tus hechizos inflige daño directo o realiza sanación directa, tienes una probabilidad de obtener Eco de los elementos, que duplica el efecto de ese hechizo.\n(100ms de reutilización)"}
MultiLanguageSpellData['mx'][108284] = {name = "Persistencia totémica", additional_info = "[q0]Talento\n[q]Invocar un segundo tótem del mismo elemento ya no provoca que el primero se destruya.\n\n Solo se puede beneficiar de este efecto un tótem a la vez. No afecta a los tótems de Fuego."}
MultiLanguageSpellData['mx'][108285] = {name = "Llamada de los elementos", additional_info = "[q0]Talento\n{Instante} {3 min de reutilización}\n[q]Cuando se activa, termina inmediatamente el tiempo de reutilización de todos los tótems con un tiempo de reutilización de base inferior a 3 min."}
MultiLanguageSpellData['mx'][108287] = {name = "Proyección totémica", additional_info = "[q0]Talento\nAlcance de 40 m\n{Instante} {10 seg de reutilización}\n[q]Traslada tus tótems activos a la ubicación especificada."}
MultiLanguageSpellData['mx'][108288] = {name = "Corazón de lo Salvaje", additional_info = "[q0]Talento\n{Instante} {6 min de reutilización}\n[q]Guardián ( Hotfix Passive )\n Aumenta un 6% el aguante, la agilidad y el intelecto en todo momento. Cuando se activa, aumenta toda la sanación realizada y mejora drásticamente la facultad del druida para realizar funciones que no son de su especialización normal durante 45 s. Otorga los siguientes beneficios en función de la especialización actual:\n\nSi no eres Guardián\n En forma de oso aumenta la agilidad, la pericia, la probabilidad de golpear, los bonus de armadura, otorga Venganza y reduce la probabilidad de recibir golpes críticos cuerpo a cuerpo.\n\nSi no eres Feral\n En forma felina, aumenta la agilidad, la probabilidad de golpear y la pericia.\n\nSi no eres Restauración\n El coste de maná de todos los hechizos de sanación se reduce un 100%. Los druidas Guardián también podrán lanzar Rejuvenecimiento cuando hayan cambiado de forma.\n\nSi no eres Equilibrio\n Aumenta el daño con hechizos y la probabilidad de golpear. El coste de maná de todos los hechizos dañinos se reduce un 100%.\n\n Equilibrio, Feral, Restauración\n Aumenta un 6% el aguante, la agilidad y el intelecto en todo momento. Cuando se activa, aumenta toda la sanación realizada y mejora drásticamente la facultad del druida para realizar funciones que no son de su especialización normal durante 45 s. Otorga los siguientes beneficios en función de la especialización actual:\n\nSi no eres Guardián\n En forma de oso aumenta la agilidad, la pericia, la probabilidad de golpear, los bonus de armadura, otorga Venganza y reduce la probabilidad de recibir golpes críticos cuerpo a cuerpo.\n\nSi no eres Feral\n En forma felina, aumenta la agilidad, la probabilidad de golpear y la pericia.\n\nSi no eres Restauración\n El coste de maná de todos los hechizos de sanación se reduce un 100%. Los druidas Guardián también podrán lanzar Rejuvenecimiento cuando hayan cambiado de forma.\n\nSi no eres Equilibrio\n Aumenta el daño con hechizos y la probabilidad de golpear. El coste de maná de todos los hechizos dañinos se reduce un 100%."}
MultiLanguageSpellData['mx'][108291] = {name = "Corazón de lo Salvaje", additional_info = "{Instante} {6 min de reutilización}\n[q]Aumenta un 6% el aguante, la agilidad y el intelecto en todo momento. Cuando se activa, mejora drásticamente la facultad del druida para realizar funciones de combate que no son de la especialización Equilibrio durante 45 s. Otorga los siguientes beneficios en las funciones descritas:\n\nGuardián\n En forma de oso, aumenta la agilidad, la pericia, la probabilidad de golpear, los bonus de armadura, otorga Venganza y reduce la probabilidad de recibir golpes críticos cuerpo a cuerpo.\n\nFeral\n En forma felina, aumenta la agilidad, la probabilidad de golpear y la pericia.\n\nRestauración\n Aumenta la sanación y se reduce un 100% el coste de maná de todos los hechizos de sanación."}
MultiLanguageSpellData['mx'][108292] = {name = "Corazón de lo Salvaje", additional_info = "{Instante} {6 min de reutilización}\n[q]Aumenta un 6% el aguante, la agilidad y el intelecto en todo momento. Cuando se activa, mejora drásticamente la facultad del druida para realizar funciones de combate que no son de la especialización Feral durante 45 s. Otorga los siguientes beneficios en las funciones descritas:\n\nGuardián\n En forma de oso, aumenta la agilidad, la pericia, la probabilidad de golpear, los bonus de armadura, otorga Venganza y reduce la probabilidad de recibir golpes críticos cuerpo a cuerpo.\n\nRestauración\n Aumenta la sanación y se reduce un 100% el coste de maná de todos los hechizos de sanación.\n\nEquilibrio\n Aumenta el daño con hechizos y la probabilidad de golpear. El coste de maná de todos los hechizos dañinos se reduce un 100%."}
MultiLanguageSpellData['mx'][108293] = {name = "Corazón de lo Salvaje", additional_info = "{Instante} {6 min de reutilización}\n[q]Aumenta un 6% el aguante, la agilidad y el intelecto en todo momento. Cuando se activa, mejora drásticamente la facultad del druida para realizar funciones de combate que no son de la especialización Guardián durante 45 s. Otorga los siguientes beneficios en las funciones descritas:\n\nFeral\n En forma felina, aumenta la agilidad, la probabilidad de golpear y la pericia.\n\nRestauración\n Aumenta la sanación y se reduce un 100% el coste de maná de todos los hechizos de sanación. Permite que se lance Rejuvenecimiento cuando se ha cambiado de forma.\n\nEquilibrio\n Aumenta el daño con hechizos y la probabilidad de golpear. El coste de maná de todos los hechizos dañinos se reduce un 100%."}
MultiLanguageSpellData['mx'][108294] = {name = "Corazón de lo Salvaje", additional_info = "{Instante} {6 min de reutilización}\n[q]Aumenta un 6% el aguante, la agilidad y el intelecto en todo momento. Cuando se activa, aumenta toda la sanación realizada un 25% y mejora drásticamente la facultad del druida para realizar funciones de combate que no son de la especialización Restauración durante 45 s. Otorga los siguientes beneficios en las funciones descritas:\n\nGuardián\n En forma de oso, aumenta la agilidad, la pericia, la probabilidad de golpear, los bonus de armadura, otorga Venganza y reduce la probabilidad de recibir golpes críticos cuerpo a cuerpo.\n\nFeral\n En forma felina, aumenta la agilidad, la probabilidad de golpear y la pericia.\n\nEquilibrio\n Aumenta el daño con hechizos y la probabilidad de golpear. El coste de maná de todos los hechizos dañinos se reduce un 100%."}
