MultiLanguageSpellData['mx'][108366] = {name = "Parasitar alma", additional_info = "Rango ilimitado\nInstante\n[q]Tu [ Aflicción : s hechizos Yugo maléfico, Drenar alma, Llama vil o Poseer les otorgan ] [ Demonología : s hechizos Descarga de las Sombras, Fuego de alma, Llama vil y Toque de caos les otorgan ] [ Destrucción : s hechizos Incinerar, Llama vil, Quemadura de las Sombras y Descarga de Caos les otorgan ] a tu mascota y a ti un escudo tenebroso que absorbe un [ Aflicción : 20% ] [ Demonología, Destrucción : 10% ] del daño infligido durante 15 s."}
MultiLanguageSpellData['mx'][108370] = {name = "Parasitar alma", additional_info = "[q0]Talento\n[q]Tu [ Aflicción : s hechizos Yugo maléfico, Drenar alma, Llama vil o Poseer les otorgan ] [ Demonología : s hechizos Descarga de las Sombras, Fuego de alma, Llama vil y Toque de caos les otorgan ] [ Destrucción : s hechizos Incinerar, Llama vil, Quemadura de las Sombras y Descarga de Caos les otorgan ] a tu mascota y a ti un escudo tenebroso que absorbe un [ Aflicción : 20% ] [ Demonología, Destrucción : 10% ] del daño infligido durante 15 s."}
