MultiLanguageSpellData['mx'][112266] = {name = "Glifo de Sentencia afilada", additional_info = "Hechizo de 3 seg 3\nHerramientas: Juego de caligrafía de virtuoso\nComponentes:\nPapiro ligero , Tinta onírica (3)\n[q9]Glifo Menor\nClases: Paladín\nNecesitas ser de nivel 25\n[q2]Uso: Te enseña permanentemente este glifo.\n\nTu Sentencia representa un hacha o espada en lugar de un martillo si tienes un hacha o una espada equipadas."}
MultiLanguageSpellData['mx'][112429] = {name = "Glifo de Festín de cuervos", additional_info = "Hechizo de 3 seg 3\nHerramientas: Juego de caligrafía de virtuoso\nComponentes:\nPapiro ligero , Tinta onírica (3)\n[q9]Glifo Menor\nClases: Guerrero\nNecesitas ser de nivel 25\n[q2]Uso: Te enseña permanentemente este glifo.\n\nLos golpes críticos de tu Ejecutar invocan a una bandada de aves carroñeras."}
MultiLanguageSpellData['mx'][112430] = {name = "Glifo de Cólera ardiente", additional_info = "Hechizo de 3 seg 3\nHerramientas: Juego de caligrafía de virtuoso\nComponentes:\nPapiro ligero , Tinta onírica (3)\n[q9]Glifo Menor\nClases: Guerrero\nNecesitas ser de nivel 25\n[q2]Uso: Te enseña permanentemente este glifo.\n\nCuando estás enfurecido te enfadas tanto que empiezas a arder."}
