MultiLanguageSpellData['mx'][112442] = {name = "Glifo de Crisálida vital", additional_info = "Hechizo de 3 seg 3\nHerramientas: Juego de caligrafía de virtuoso\nComponentes:\nPapiro ligero , Tinta etérea (3)\n[q9]Glifo Sublime\nClases: Monje\nNecesitas ser de nivel 25\n[q2]Uso: Te enseña permanentemente este glifo.\n\nAhora puedes lanzar Crisálida vital mientras estás aturdido."}
