MultiLanguageSpellData['mx'][112457] = {name = "Glifo de Brebaje reconstituyente", additional_info = "Hechizo de 3 seg 3\nHerramientas: Juego de caligrafía de virtuoso\nComponentes:\nPapiro ligero , Tinta fulgurante (3)\n[q9]Glifo Sublime\nClases: Monje\nNecesitas ser de nivel 25\n[q2]Uso: Te enseña permanentemente este glifo.\n\nTu Brebaje reconstituyente reduce el daño recibido un 5% extra, pero aumenta tu salud un 10% en lugar de un 20 %."}
MultiLanguageSpellData['mx'][112458] = {name = "Glifo de Expulsión dirigida", additional_info = "Hechizo de 3 seg 3\nHerramientas: Juego de caligrafía de virtuoso\nComponentes:\nPapiro ligero , Tinta del mar (3)\n[q9]Glifo Sublime\nClases: Monje\nNecesitas ser de nivel 25\n[q2]Uso: Te enseña permanentemente este glifo.\n\n[ Tejedor de niebla : Fuera de campos de batalla y arenas:\n Tu Inspirar ya no cuesta chi, sino que cuesta un 10% de maná.\n\n Dentro de campos de batalla y arenas: ]Expulsar daño ahora se puede usar en otros aliados, pero la sanación se reduce un 50% en ellos."}
MultiLanguageSpellData['mx'][112460] = {name = "Glifo de Vuelo zen", additional_info = "Hechizo de 3 seg 3\nHerramientas: Juego de caligrafía de virtuoso\nComponentes:\nPapiro ligero , Tinta onírica (3)\n[q9]Glifo Menor\nClases: Monje\nNecesitas ser de nivel 25\n[q2]Uso: Te enseña permanentemente este glifo.\n\nTe enseña el hechizo Vuelo zen. Lanzar Vuelo zen requiere Licencia de maestro de vuelo.\n\nVuelo zen\nVuelas por el aire a gran velocidad sobre una nube meditativa."}
