MultiLanguageSpellData['mx'][112463] = {name = "Glifo de Patada del dragón volador", additional_info = "Hechizo de 3 seg 3\nHerramientas: Juego de caligrafía de virtuoso\nComponentes:\nPapiro ligero , Tinta del mar (3)\n[q9]Glifo Menor\nClases: Monje\nNecesitas ser de nivel 25\n[q2]Uso: Te enseña permanentemente este glifo.\n\nTu Patada del dragón volador acaba automáticamente cuando te topas con un enemigo, lo que activa el daño de área de efecto y el frenado."}
MultiLanguageSpellData['mx'][112464] = {name = "Glifo de Honor", additional_info = "Hechizo de 3 seg 3\nHerramientas: Juego de caligrafía de virtuoso\nComponentes:\nPapiro ligero , Tinta onírica (3)\n[q9]Glifo Menor\nClases: Monje\nNecesitas ser de nivel 25\n[q2]Uso: Te enseña permanentemente este glifo.\n\nHaces una reverencia tras cada Toque de la muerte con éxito."}
