MultiLanguageSpellData['mx'][112859] = {name = "Perspicacia Sagrada", additional_info = "[q]Aumenta la efectividad de tu sanación un 25% y tu Palabra de gloria, Llama eterna y Luz del alba un 50%.\n\n Aumenta tu reserva de maná un 400%.\n\n Permite que un 50% de tu regeneración de maná de Espíritu continúe mientras estás en combate.\n\n Aumenta tu probabilidad de golpear con Choque sagrado, Juicio, [ Glifo de Duras palabras : Duras palabras ]y Acusar un 15%.\n\n Aumenta tu probabilidad de golpear con Golpe de cruzado un 7.5% mientras estás fuera de las Arenas y los Campos de Batalla."}
MultiLanguageSpellData['mx'][112865] = {name = "Veneno agresivo", additional_info = "Rango ilimitado\nInstante\n[q]Inflige 3500 to 4500 p. de daño de Naturaleza a un enemigo cada 2 s durante 12 s."}
MultiLanguageSpellData['mx'][112866] = {name = "Invocar diablillo vil", additional_info = "20% del maná base / 20% del furia demoníaca base\nHechizo de 5 seg\n[q]Invoca a un diablillo vil a las órdenes del brujo.\n\n Los diablillos viles pueden lanzar Descarga de Fuego vil a distancia [ Diablillo: Cauterizar al amo : sanar a su amo en el tiempo ] [ Diablillo: Carbonizar magia : disipar efectos mágicos hostiles ] . [ Quemar alma : Quemar alma:\nLanzamiento instantáneo. ]"}
MultiLanguageSpellData['mx'][112867] = {name = "Invocar señor del vacío", additional_info = "25% del maná base / 20% del furia demoníaca base\nHechizo de 5 seg\n[q]Invoca a un señor del vacío a las órdenes del brujo.\n\n Los señores del vacío pueden soportar potentes ataques [ Abisario: Desarmar : desarmar a los atacantes cuerpo a cuerpo ] [ Abisario: Escudo de las Sombras : infligir daño de las Sombras a los enemigos que los dañan ] [ Abisario: Baluarte de las Sombras : aumentar su salud cuando se encuentran cerca de la muerte ] [ Abisario: Sufrimiento : y provocar a los enemigos que atacan a su amo / . ] [ Quemar alma : Quemar alma:\nLanzamiento instantáneo. ]"}
MultiLanguageSpellData['mx'][112868] = {name = "Invocar shivarra", additional_info = "25% del maná base / 20% del furia demoníaca base\nHechizo de 5 seg\n[q]Invoca a una shivarra a las órdenes del brujo.\n\n Las shivarras son peligrosas hechiceras de corto alcance. Pueden [ Súcubo: Invisibilidad inferior : volverse invisibles ] [ Súcubo: Anguilazo : repeler a los enemigos ] [ Súcubo: Invisibilidad inferior : y ] embelesar a sus oponentes, lo que les impide atacar. [ Quemar alma : Quemar alma:\nLanzamiento instantáneo. ]"}
MultiLanguageSpellData['mx'][112869] = {name = "Invocar observador", additional_info = "25% del maná base / 20% del furia demoníaca base\nHechizo de 5 seg\n[q]Invoca a un observador a las órdenes del brujo.\n\n A los observadores les atrae la magia [ Manáfago: Bloqueo de hechizo : pueden utilizar poderosos ataques ópticos que interrumpen el lanzamiento de hechizos ] y se sanan al consumir los efectos mágicos beneficiosos de sus enemigos. [ Quemar alma : Quemar alma:\nLanzamiento instantáneo. ]"}
MultiLanguageSpellData['mx'][112870] = {name = "Invocar guardia de cólera", additional_info = "25% del maná base / 20% del furia demoníaca base\nHechizo de 5 seg\n[q]Invoca a un guardia de cólera a las órdenes del brujo.\n\n Los guardias de cólera son fuertes luchadores cuerpo a cuerpo que sobresalen en el combate contra varios objetivos [ Guardia vil: Tormenta Vil : pueden realizar un poderoso ataque en área ] [ Guardia vil: Lanzamiento de hachas : aturdir a un oponente a distancia ] y reducir la sanación recibida de su objetivo."}
