MultiLanguageSpellData['mx'][113858] = {name = "Alma oscura: Inestabilidad", additional_info = "5% del maná base\n{Instante} {2 min de reutilización}\n[q]Infunde poder inestable en tu alma, lo que aumenta tu probabilidad de golpe crítico un 30% durante 20 s.\n [\nPasivo:\n Aumenta tu probabilidad de golpe crítico un 3%. Este efecto se desactiva durante el tiempo de reutilización.]"}
MultiLanguageSpellData['mx'][113859] = {name = "Bomba Arcana", additional_info = "Instante\n[q]Una explosión de energía mágica inflige 92500 to 107500 p. de daño Arcano."}
MultiLanguageSpellData['mx'][113860] = {name = "Alma oscura: Angustia", additional_info = "5% del maná base\n{Instante} {2 min de reutilización}\n[q]Infunde la angustia de los héroes caídos en tu alma, lo que aumenta la celeridad con hechizos un 30% durante 20 s.\n [\nPasivo:\n Aumenta tu celeridad con hechizos un 3%. Este efecto se desactiva durante el tiempo de reutilización.]"}
MultiLanguageSpellData['mx'][113861] = {name = "Alma oscura: Conocimiento", additional_info = "5% del maná base\n{Instante} {2 min de reutilización}\n[q]Infunde en tu alma conocimiento demoníaco, lo que aumenta los efectos de tu Maestría: Maestro demonólogo un 30% extra durante 20 s. [ Glifo de Alma oscura : Pasivo:\n Aumenta los efectos de tu Maestría: Maestro demonólogo un 3% extra. Este efecto se desactiva durante el tiempo de reutilización ]"}
MultiLanguageSpellData['mx'][113862] = {name = "Invisibilidad superior", additional_info = "Instante\n[q]Vuelve instantáneamente invisible al taumaturgo, reduce toda la amenaza y elimina 2 efectos de daño en el tiempo. Mientras estás invisible, los enemigos no te pueden seleccionar como objetivo. Dura 20 s. [ Glifo de Invisibilidad : Te mueves un 40% más rápido mientras permaneces invisible ] El efecto se anulará si realizas cualquier tipo de acción.\n\n El daño recibido se reduce un 90% mientras permaneces invisible y durante 3 s después de que te vuelvas visible.\n\n Reemplaza a Invisibilidad."}
