MultiLanguageSpellData['mx'][114003] = {name = "Invocación", additional_info = "[q0]Talento\n[q]Elimina el tiempo de reutilización de Evocación y reduce un 50% su periodo de canalización y duración.\n\n Completar una Evocación provoca que inflijas un 15% más de daño con hechizos, pero que regeneres de forma pasiva un 50% menos de maná durante 1 min."}
MultiLanguageSpellData['mx'][114004] = {name = "Lanzamiento perforador", additional_info = "Alcance de 100 m\nCanalizado (Hechizo de 2 seg)\n[q]El maestro de canes Braun lanza uno de sus cuchillos a un enemigo aleatorio, lo que inflige 105000 p. de daño físico y aplica Carnicería sangrienta a todos los enemigos al paso del cuchillo."}
MultiLanguageSpellData['mx'][114006] = {name = "Bramido profundo", additional_info = "Alcance de ataques cuerpo a cuerpo\n{Instante} {5 seg de reutilización}\n[q]Reduce la armadura de los enemigos cercanos durante 10 s."}
MultiLanguageSpellData['mx'][114007] = {name = "Llama del alma", additional_info = "Instante\n[q]Crea un charco de lágrimas acres que inflige daño de Naturaleza y crece de tamaño con el tiempo."}
MultiLanguageSpellData['mx'][114009] = {name = "Llama del alma", additional_info = "Instante\n[q]Una llama del alma refulgente inflige 141375 to 158625 p. de daño de Fuego a los enemigos cercanos y crece con el tiempo."}
MultiLanguageSpellData['mx'][114011] = {name = "Rajar armadura", additional_info = "Alcance de ataques cuerpo a cuerpo\nInstante\n[q]Inflige un 150% de daño con arma y aumenta el daño físico recibido un 20% durante 10 s. Se acumula."}
MultiLanguageSpellData['mx'][114013] = {name = "Versatilidad", additional_info = "[q]Tu facultad Redirigir ya no tiene tiempo de reutilización.\n[q]Modifies Cooldown -60000:\nRedirigir"}
MultiLanguageSpellData['mx'][114014] = {name = "Lanzamiento de shuriken", additional_info = "[q0]Talento\n[q]Sustituye Lanzar\n{40 p. de energía} {Alcance de 30 m}\nInstante\n[q]Un ataque a distancia que inflige 2493 p. de daño físico a un objetivo enemigo. Si el enemigo está a más de 10 m de distancia, tus ataques automáticos se reemplazarán por shurikens a distancia durante un máximo de 10 s, lo que les otorga un alcance de 30 m. Los shurikens están cubiertos de tu veneno letal. Otorga 1 p. de combo.\n\n Reemplaza a Lanzar."}
MultiLanguageSpellData['mx'][114015] = {name = "Anticipación", additional_info = "[q0]Talento\n[q]Cuando uno de tus ataques genera un punto de combo en un objetivo que ya tiene 5 p. de combo, obtienes una carga de Anticipación, hasta un máximo de 5 cargas.\n\n Cuando realizas un remate ofensivo contra un enemigo, todas las cargas de Anticipación se consumen para otorgarte la misma cantidad de puntos de combo sobre el mismo objetivo."}
MultiLanguageSpellData['mx'][114016] = {name = "Carrera del toro", additional_info = "Alcance de 8 - 30 mHechizo de 1 seg 5 seg de reutilización\n[q]Carga contra la ubicación actual de un objetivo enemigo, lo que aumenta la velocidad de movimiento un 60% durante 3 s. Al alcanzar el destino, derriba a todos los enemigos cercanos."}
