MultiLanguageSpellData['mx'][115069] = {name = "Estilo del buey robusto", additional_info = "Instante\n[q]Reduce el daño recibido un 25%. Aumenta la regeneración de energía un 10%. Reduce la probabilidad de recibir golpes críticos un 6%. Aumenta tu aguante un 20% y te permite aplazar daño.\n\nAplazar\nAplazas los ataques físicos, lo que provoca que el 80% de su daño se inflija al instante y el 20% restante se reparta durante 10 s."}
MultiLanguageSpellData['mx'][115070] = {name = "Estilo del dragón sabio", additional_info = "Instante\n[q]Aumenta la sanación realizada un 20% y sustituye tu recurso de energía con maná. También otorga golpe y pericia equivalente a un 50% del espíritu obtenido mediante objetos o efectos.\n\n Aumenta la celeridad obtenida de objetos un 50%. Tu poder de ataque es igual a un 200% de tu poder con hechizos, pero ya no te beneficias de otras fuentes de poder de ataque.\n\n Además, también obtienes Eminencia, lo que sana al objetivo cercano con menos salud en un radio de 20 m una cantidad equivalente al 25% del daño infligido no derivado de los ataques automáticos."}
MultiLanguageSpellData['mx'][115071] = {name = "A Zandalari Troll?: Ribbon of Souls Fountain", additional_info = nil}
MultiLanguageSpellData['mx'][115072] = {name = "Expulsar daño", additional_info = "{2.5% del maná base} {/ 40 p. de energía}\n{Instante} {15 seg de reutilización}\nRequiere Estilo del dragón, Estilo del buey, Estilo del tigre\n[q]Recuperas instantáneamente de [7 * ( 1 * ( 0.898882 * (Mainhand Min DPS * [0.75] 1 + 0 ) + (Attack power / 14) - 1))] a [7 * ( 1 * ( 0.898882 * (Mainhand Max DPS * [0.75] 1 + 0 ) + (Attack power / 14) + 1))] p. de salud y hace que un 50 % de la cantidad sanada se inflija al instante como daño de Naturaleza a un enemigo cercano en un radio de 10 m. Genera 1 p. de chi."}
MultiLanguageSpellData['mx'][115073] = {name = "Flor de fuego giratoria", additional_info = "{1 de chi} {Alcance de 50 m}\nHechizo instantáneo\n[q]Inflige [2.1 * ( 1 * 1 * ( 0.898882 * (Mainhand Min DPS * 1 + 1 * (Mainhand Min DPS / 2) ) + (Attack power / 14) - 1))] - [2.1 * ( 1 * 1 * ( 0.898882 * (Mainhand Max DPS * 1 + 1 * (Mainhand Max DPS / 2) ) + (Attack power / 14) + 1))] p. de daño de Fuego al primer enemigo frente a ti en un radio de 50 m.\n\n Si Flor de fuego giratoria se desplaza más de 10 m, el daño aumenta un 50% y enraíza al objetivo durante 2 s."}
MultiLanguageSpellData['mx'][115074] = {name = "Estilo de lucha", additional_info = "[q]La facultad Atizar del monje cambia dependiendo del arma que tengas equipada y altera la apariencia del estilo de lucha del monje. El daño y el coste de recursos no cambian."}
MultiLanguageSpellData['mx'][115075] = {name = "Golpe de brebaje relámpago", additional_info = "Alcance de 50 m\nInstante\n[q]Electrocutando al saurok objetivo con energía eléctrica, lo que lo enraíza. ¡Tus amigos pueden aporrear a tu objetivo para rematarlo!"}
