MultiLanguageSpellData['mx'][115180] = {name = "Estupor mareante", additional_info = "{20 p. de energía} {Alcance de 40 m}\nInstante\nRequiere Estilo del buey\n[q]Lanzas un barril de tu mejor cerveza, lo que reduce un 50% la velocidad de movimiento de todos los enemigos en un radio de 8 m durante 15 s. Genera una gran cantidad de amenaza.\n\n Los objetivos afectados tienen un 3% de probabilidad de fallar sus ataques cuerpo a cuerpo y de golpearse a sí mismos, lo que les inflige 1095 p. de daño."}
MultiLanguageSpellData['mx'][115181] = {name = "Aliento de Fuego", additional_info = "2 de chi\nHechizo instantáneo\nRequiere Estilo del buey\n[q]Lanzas un aliento de fuego que inflige 1615 p. de daño a todos los objetivos frente a ti en un radio de 8 m.\n\n Si Estupor mareante está activo en los objetivos, reciben 2080 p. de daño extra durante 8 s [ Glifo de Aliento de Fuego : y quedan desorientados durante 3 s / .]"}
