MultiLanguageSpellData['mx'][115294] = {name = "Té de maná", additional_info = "Canalizado (Hechizo de 3 seg)\nRequiere Estilo del dragón\n[q]Tejedor de niebla ( Hotfix Passive )\n Restaura un 5% de tu maná máximo por cada acumulación de té de maná activa. El té de maná se canaliza y dura 0.5 s por acumulación. Cancelar la canalización no desperdicia acumulaciones.\n\n\n Restaura un 4 % de tu maná máximo por cada acumulación de té de maná activa. El té de maná se canaliza y dura 0.5 s por acumulación. Cancelar la canalización no desperdicia acumulaciones."}
MultiLanguageSpellData['mx'][115295] = {name = "Guardia", additional_info = "2 de chi\n{Hechizo instantáneo} {30 seg de reutilización}\nRequiere Estilo del buey\n[q]Te pones en guardia contra futuros ataques, lo que absorbe [(Attack power * 1.971) + 14232 ] p. de daño durante 30 s.\n\n Aumenta un 30 % todas las sanaciones que realices sobre ti mismo mientras estás en guardia."}
