MultiLanguageSpellData['mx'][115307] = {name = "Deslizarse", additional_info = "Instante\nRequiere Estilo del buey\n[q]Entrenamiento de maestro cervecero\n Requires Monk (Maestro cervecero)\n Requires level 34 Te conviertes en un experto en las técnicas del maestro cervecero, lo que mejora tres de tus facultades.\n\nBrebaje reconstituyente\n También aumenta la cantidad de daño que pospone tu Aplazar un 20% mientras está activo.\n\nPalma del tigre\n Palma del tigre ya no cuesta chi. Cuando Palma del tigre inflige daño, aumenta la absorción de tu siguiente Guardia un 15 %. Dura 30 s.\n\nPatada oscura\n Cuando asestas una Patada oscura, obtienes Deslizarse, lo que aumenta tu probabilidad de parada un 20% y la cantidad de daño que pospone tu Aplazar un 20% extra durante 6 s."}
MultiLanguageSpellData['mx'][115308] = {name = "Brebaje esquivo", additional_info = "{Instante} {6 seg de reutilización}\nRequiere Estilo del buey\n[q]Aumenta tu probabilidad de esquivar ataques cuerpo a cuerpo y a distancia un 30 % durante 1 s por acumulación de Brebaje esquivo activa, lo que consume tus cargas de Brebaje esquivo."}
MultiLanguageSpellData['mx'][115309] = {name = "Alma expulsada", additional_info = "Canalizado (Hechizo de 0 seg)\n[q]El alma expulsada atacará al objetivo más cercano que no es su creador."}
MultiLanguageSpellData['mx'][115310] = {name = "Reanimación", additional_info = "7.7% del maná base\n{Instante} {3 min de reutilización}\nRequiere Estilo del dragón\n[q]Sana instantáneamente 9579 p. a todos los miembros del grupo o banda que estén en un radio de 100 m y elimina cualquier efecto dañino mágico, de veneno y de enfermedad."}
MultiLanguageSpellData['mx'][115311] = {name = "Embate con bastón", additional_info = "1 Felicidad Alcance de ataques cuerpo a cuerpo\n{Hechizo instantáneo} {6 seg de reutilización}\nRequiere Estilo del buey, Estilo del tigre\n[q]Golpeas al enemigo con tu bastón y le infliges un 250% de daño con arma. Atacas con tanta fuerza que el propio golpe te inflige un daño equivalente a un 20% del daño infligido.\n\n Si esquivas o absorbes totalmente el daño del retroceso, obtienes 2 p. de fuerza oscura."}
MultiLanguageSpellData['mx'][115313] = {name = "Invocar estatua del Dragón de Jade", additional_info = "Alcance de 40 m\n{Instante} {30 seg de reutilización}\nRequiere Estilo del dragón\n[q]Tejedor de niebla ( Hotfix Passive )\n Invoca una estatua del Dragón de Jade en la ubicación objetivo. Dura 15 min. Solo puede haber una estatua activa a la vez.\n\nEminencia (Pasivo)\nCada vez que el monje inflige daño no derivado de ataques automáticos, la estatua del Dragón de Jade invocada sanará al objetivo cercano con menos salud en un radio de 20 m una cantidad equivalente al 42% del daño infligido.\n\nBálsamo de dragón (pasivo)\n Cuando lanzas Niebla reconfortante, la estatua del Dragón de Jade también lanza Niebla reconfortante sobre un aliado herido en un radio de 40 m.\n\n\n Invoca una estatua del Dragón de Jade en la ubicación objetivo. Dura 15 min. Solo puede haber una estatua activa a la vez.\n\nEminencia (Pasivo)\nCada vez que el monje inflige daño no derivado de ataques automáticos, la estatua del Dragón de Jade invocada sanará al objetivo cercano con menos salud en un radio de 20 m una cantidad equivalente al 25% del daño infligido.\n\nBálsamo de dragón (pasivo)\n Cuando lanzas Niebla reconfortante, la estatua del Dragón de Jade también lanza Niebla reconfortante sobre un aliado herido en un radio de 40 m."}
MultiLanguageSpellData['mx'][115314] = {name = "Glifo de Iluminación", additional_info = "Instante\n[q]Devuelve un 1% de tu maná máximo con un golpe crítico de Choque Sagrado."}
MultiLanguageSpellData['mx'][115315] = {name = "Invocar estatua del Buey Negro", additional_info = "Alcance de 40 m\n{Instante} {30 seg de reutilización}\nRequiere Estilo del buey\n[q]Invoca una estatua del Buey Negro en la ubicación seleccionada. Dura 15 min. Solo se puede invocar una estatua del Buey Negro a la vez.\n\n La estatua del Buey Negro interactúa con tus facultades Burla y Mirada del buey.\n\nSantuario del buey (pasivo)\nCada vez que el monje inflige (Attack power * 16) p. de daño, la estatua del Buey Negro lanza Guardia sobre un miembro herido del grupo o banda en un radio de 40 m, lo que absorbe [((Attack power * 1.971) + 14232 ) * 1 ] p. de daño y dura 30 s. Este efecto no se puede lanzar sobre el monje."}
MultiLanguageSpellData['mx'][115317] = {name = "Viento furioso", additional_info = "Alcance de 100 m\nInstante\n[q]Los golpes de tu Arremetida enfurecida aumentan un 10 % el daño de tu próximo Torbellino."}
