MultiLanguageSpellData['mx'][124442] = {name = "Glifo de Aspecto de la bestia", additional_info = "Hechizo de 3 seg 3\nHerramientas: Juego de caligrafía de virtuoso\nComponentes:\nPapiro ligero , Tinta del mar (3)\n[q9]Glifo Menor\nClases: Cazador\nNecesitas ser de nivel 25\n[q2]Uso: Te enseña permanentemente este glifo.\n\nTe enseña la facultad Aspecto de la bestia.\n\n El cazador asume el aspecto de una bestia y se vuelve imposible de rastrear. Solo puede haber un aspecto activo cada vez."}
MultiLanguageSpellData['mx'][124443] = {name = "Glifo de Suelo resbaladizo", additional_info = "Hechizo de 3 seg 3\nHerramientas: Juego de caligrafía de virtuoso\nComponentes:\nPapiro ligero , Tinta onírica (3)\n[q9]Glifo Sublime\nClases: Cazador\nNecesitas ser de nivel 25\n[q2]Uso: Te enseña permanentemente este glifo.\n\nMientras te mueves por el área afectada por tu Trampa de hielo, ganas un 50% de velocidad de movimiento."}
MultiLanguageSpellData['mx'][124444] = {name = "Glifo de Aliento de Fuego", additional_info = "Hechizo de 3 seg 3\nHerramientas: Juego de caligrafía de virtuoso\nComponentes:\nPapiro ligero , Tinta onírica (3)\n[q9]Glifo Sublime\nClases: Monje\nNecesitas ser de nivel 25\n[q2]Uso: Te enseña permanentemente este glifo.\n\nCuando utilizas Aliento de Fuego contra objetivos afectados por tu Estupor mareante, estos quedan desorientados durante 3 s."}
MultiLanguageSpellData['mx'][124445] = {name = "Glifo de Puños de furia", additional_info = "Hechizo de 3 seg 3\nHerramientas: Juego de caligrafía de virtuoso\nComponentes:\nPapiro ligero , Tinta del mar (3)\n[q9]Glifo Sublime\nClases: Monje\nNecesitas ser de nivel 25\n[q2]Uso: Te enseña permanentemente este glifo.\n\nAl canalizar Puños de furia, tu probabilidad de parada aumenta un 100%."}
MultiLanguageSpellData['mx'][124446] = {name = "Glifo de Colisión", additional_info = "Hechizo de 3 seg 3\nHerramientas: Juego de caligrafía de virtuoso\nComponentes:\nPapiro ligero , Tinta onírica (3)\n[q9]Glifo Sublime\nClases: Monje\nNecesitas ser de nivel 25\n[q2]Uso: Te enseña permanentemente este glifo.\n\nAumenta el alcance de tu facultad Colisión 10 m."}
