MultiLanguageSpellData['mx'][124448] = {name = "Glifo de Rodar rápido", additional_info = "Hechizo de 3 seg 3\nHerramientas: Juego de caligrafía de virtuoso\nComponentes:\nPapiro ligero , Tinta onírica (3)\n[q9]Glifo Sublime\nClases: Monje\nNecesitas ser de nivel 25\n[q2]Uso: Te enseña permanentemente este glifo.\n\nDurante 5 s s después de usar Rodar o Torpedo de chi, tu próximo Rodar o Torpedo de chi irá un 30% más lejos."}
MultiLanguageSpellData['mx'][124449] = {name = "Glifo de Guardia", additional_info = "Hechizo de 3 seg 3\nHerramientas: Juego de caligrafía de virtuoso\nComponentes:\nPapiro ligero , Tinta onírica (3)\n[q9]Glifo Sublime\nClases: Monje\nNecesitas ser de nivel 25\n[q2]Uso: Te enseña permanentemente este glifo.\n\nAumenta un 10% la cantidad de absorción de Guardia, pero solo puede absorber daño mágico."}
MultiLanguageSpellData['mx'][124450] = {name = "Glifo de Té de maná", additional_info = "Hechizo de 3 seg 3\nHerramientas: Juego de caligrafía de virtuoso\nComponentes:\nPapiro ligero , Tinta onírica (3)\n[q9]Glifo Sublime\nClases: Monje\nNecesitas ser de nivel 25\n[q2]Uso: Te enseña permanentemente este glifo.\n\nTu Té de maná es instantáneo en lugar de canalizado y consume dos acumulaciones al utilizarse, pero adquiere un tiempo de reutilización de 10 s."}
MultiLanguageSpellData['mx'][124451] = {name = "Glifo de Meditación zen", additional_info = "Hechizo de 3 seg 3\nHerramientas: Juego de caligrafía de virtuoso\nComponentes:\nPapiro ligero , Tinta del mar (3)\n[q9]Glifo Sublime\nClases: Monje\nNecesitas ser de nivel 25\n[q2]Uso: Te enseña permanentemente este glifo.\n\nAhora puedes canalizar Meditación zen mientras te mueves."}
MultiLanguageSpellData['mx'][124452] = {name = "Glifo de Niebla renovadora", additional_info = "Hechizo de 3 seg 3\nHerramientas: Juego de caligrafía de virtuoso\nComponentes:\nPapiro ligero , Tinta del mar (3)\n[q9]Glifo Sublime\nClases: Monje\nNecesitas ser de nivel 25\n[q2]Uso: Te enseña permanentemente este glifo.\n\nTu Niebla renovadora viaja hasta el objetivo herido más lejano en un radio de 40 m, en lugar del objetivo herido más cercano en un radio de 20 m."}
MultiLanguageSpellData['mx'][124453] = {name = "Glifo de Patada giratoria de la grulla", additional_info = "Hechizo de 3 seg 3\nHerramientas: Juego de caligrafía de virtuoso\nComponentes:\nPapiro ligero , Tinta del mar (3)\n[q9]Glifo Sublime\nClases: Monje\nNecesitas ser de nivel 25\n[q2]Uso: Te enseña permanentemente este glifo.\n\nTe mueves a velocidad máxima mientras canalizas Patada giratoria de la grulla."}
MultiLanguageSpellData['mx'][124454] = {name = "Glifo de Flor de fuego giratoria", additional_info = "Hechizo de 3 seg 3\nHerramientas: Juego de caligrafía de virtuoso\nComponentes:\nPapiro ligero , Tinta onírica (3)\n[q9]Glifo Menor\nClases: Monje\nNecesitas ser de nivel 25\n[q2]Uso: Te enseña permanentemente este glifo.\n\nTu Flor de fuego giratoria requiere un objetivo en lugar de desplazarse frente a ti, pero ya no puede enraizar a los objetivos."}
MultiLanguageSpellData['mx'][124455] = {name = "Glifo de Oleada de niebla", additional_info = "Hechizo de 3 seg 3\nHerramientas: Juego de caligrafía de virtuoso\nComponentes:\nPapiro ligero , Tinta del mar (3)\n[q9]Glifo Sublime\nClases: Monje\nNecesitas ser de nivel 25\n[q2]Uso: Te enseña permanentemente este glifo.\n\nTu Oleada de niebla ya no requiere un objetivo; en su lugar, sana al objetivo con menos salud en un radio de 40 m."}
MultiLanguageSpellData['mx'][124456] = {name = "Glifo de Toque de la muerte", additional_info = "Hechizo de 3 seg 3\nHerramientas: Juego de caligrafía de virtuoso\nComponentes:\nPapiro ligero , Tinta del mar (3)\n[q9]Glifo Sublime\nClases: Monje\nNecesitas ser de nivel 25\n[q2]Uso: Te enseña permanentemente este glifo.\n\nTu Toque de la muerte ya no cuesta chi, pero su tiempo de reutilización aumenta 2 min."}
MultiLanguageSpellData['mx'][124457] = {name = "Glifo de Transcendencia", additional_info = "Hechizo de 3 seg 3\nHerramientas: Juego de caligrafía de virtuoso\nComponentes:\nPapiro ligero , Tinta onírica (3)\n[q9]Glifo Sublime\nClases: Monje\nNecesitas ser de nivel 25\n[q2]Uso: Te enseña permanentemente este glifo.\n\nReduce el tiempo de reutilización de tu Transcendencia: Transferencia 5 s."}
MultiLanguageSpellData['mx'][124458] = {name = "Esfera de sanación", additional_info = "Rango ilimitado\nInstante\n[q]Formas una esfera de sanación con niebla sanadora en la ubicación objetivo durante 1 min. Si los aliados la atraviesan, consumen la esfera y sanan [((Attack power * 0.75) + 9986 )] p. de salud.\n\n El monje puede activar hasta un máximo de 3 esferas de sanación al mismo tiempo.\n\n Si la esfera de sanación desaparece antes de ser utilizada, un aliado cercano en un radio de 6 m de la esfera sanará un 50% del efecto."}
MultiLanguageSpellData['mx'][124459] = {name = "Glifo de Tortura mental", additional_info = "Hechizo de 3 seg 3\nHerramientas: Juego de caligrafía de virtuoso\nComponentes:\nPapiro ligero , Tinta celestial (3)\n[q9]Glifo Sublime\nClases: Sacerdote\nNecesitas ser de nivel 25\n[q2]Uso: Te enseña permanentemente este glifo.\n\nTu hechizo Tortura mental ya no reduce la velocidad de movimiento de tu víctima. En su lugar, cada vez que Tortura mental inflija daño tu velocidad de movimiento aumentará un 15% durante 5 s. Se acumula hasta 3 veces."}
MultiLanguageSpellData['mx'][124460] = {name = "Glifo de Abrazo vampírico", additional_info = "Hechizo de 3 seg 3\nHerramientas: Juego de caligrafía de virtuoso\nComponentes:\nPapiro ligero , Tinta onírica (3)\n[q9]Glifo Sublime\nClases: Sacerdote\nNecesitas ser de nivel 25\n[q2]Uso: Te enseña permanentemente este glifo.\n\nTu Abrazo vampírico convierte un 50% extra del daño que infliges en sanación, pero su duración se reduce 5 s."}
MultiLanguageSpellData['mx'][124461] = {name = "Glifo de Palabra de las Sombras: muerte", additional_info = "Hechizo de 3 seg 3\nHerramientas: Juego de caligrafía de virtuoso\nComponentes:\nPapiro ligero , Tinta onírica (3)\n[q9]Glifo Sublime\nClases: Sacerdote\nNecesitas ser de nivel 25\n[q2]Uso: Te enseña permanentemente este glifo.\n\nTu Palabra de las Sombras: muerte ahora se puede lanzar en cualquier momento, pero inflige un 25% de daño contra los objetivos que estén por encima del 20% de salud [ Tortura mental : y no genera un orbe de las Sombras cuando se usa contra ellos ].\n\n Lanzar Palabra de las Sombras: muerte ahora también te inflige daño equivalente al daño que le infligiría a un enemigo por encima del 20% de salud."}
MultiLanguageSpellData['mx'][124463] = {name = "Glifo de Esferas fortuitas", additional_info = "Hechizo de 3 seg 3\nHerramientas: Juego de caligrafía de virtuoso\nComponentes:\nPapiro ligero , Tinta del mar (3)\n[q9]Glifo Sublime\nClases: Monje\nNecesitas ser de nivel 25\n[q2]Uso: Te enseña permanentemente este glifo.\n\nSi la salud baja de un 25%, se invocará automáticamente una esfera de sanación cerca de ti sin coste alguno. Este efecto no se puede producir más de una vez cada 30 s. (30s de reutilización)"}
