MultiLanguageSpellData['mx'][124465] = {name = "Toque vampírico", additional_info = "Alcance de 100 m\nInstante\n[q]Inflige 5 p. de daño de las Sombras durante 15 s. Cada vez que Toque vampírico inflige daño, el taumaturgo obtiene un 2 % de su maná máximo."}
MultiLanguageSpellData['mx'][124466] = {name = "Glifo de los cielos", additional_info = "Hechizo de 3 seg 3\nHerramientas: Juego de caligrafía de virtuoso\nComponentes:\nPapiro ligero , Tinta onírica (3)\n[q9]Glifo Menor\nClases: Sacerdote\nNecesitas ser de nivel 25\n[q2]Uso: Te enseña permanentemente este glifo.\n\nTus objetivos de Levitar parecerán que se desplazan sobre una nube mientras dure el hechizo."}
MultiLanguageSpellData['mx'][124467] = {name = "Peste devoradora", additional_info = "Alcance de 100 m\nInstante\n[q]Consume todos los orbes de las sombras del taumaturgo para infligir 0 p. de daño de las Sombras y 0 p. de daño de las Sombras más cada 1.00 s durante 6 s. También sana al taumaturgo ( 100 / 100)% p. de su salud máxima cuando inflige daño periódico.\n\n El daño y la sanación aumentan según la cantidad de orbes de las sombras consumidos. [ Consuelo y demencia : Mientras Peste devoradora está activa, el daño de tu Tortura mental aumenta un 33% por orbe consumido ]"}
MultiLanguageSpellData['mx'][124468] = {name = "Tortura mental", additional_info = "Alcance de 100 m\nInstante\n[q]Ofusca la mente del objetivo con energía de las Sombras, lo que le inflige 3148 p. de daño de las Sombras durante 3 s [ Glifo de Tortura mental : Cada vez que Tortura mental inflige daño, el sacerdote recibe un 15% extra de velocidad de movimiento durante 5 s. Se acumula un máximo de 3 veces / y ralentiza su velocidad de movimiento un 50 %.]"}
