MultiLanguageSpellData['mx'][132409] = {name = "Bloqueo de hechizo", additional_info = "{2% del maná base} {Alcance de 40 m}\n{Instante} {24 seg de reutilización}\n[q]Silencia al enemigo durante 3 s. Si el objetivo está lanzando hechizos, contrarrestará el lanzamiento del enemigo y evitará que se lancen hechizos de ese tipo de magia durante 6 s."}
MultiLanguageSpellData['mx'][132410] = {name = "Perseguir", additional_info = "{2% del maná base} {Alcance de 8 - 25 m}\n{Instante} {15 seg de reutilización}\n[q]Carga contra un enemigo, lo que inflige al instante un 100 % de daño con arma y aumenta la velocidad de movimiento del [ Grimorio de supremacía : guardia de cólera / guardia vil] un 30% durante 6 s.\n\nLanzamiento automático:\n Se usa cuando el [ Grimorio de supremacía : guardia de cólera / guardia vil] está a más de 8 m.\n\n(Clic derecho para activar)"}
MultiLanguageSpellData['mx'][132411] = {name = "Carbonizar magia", additional_info = "{3% del maná base} {Alcance de 30 m}\n{Instante} {10 seg de reutilización}\n[q]Quema la magia dañina del objetivo, lo que elimina 1 hechizo dañino de un amigo."}
MultiLanguageSpellData['mx'][132412] = {name = "Seducción", additional_info = "{2% del maná base} {Alcance de 30 m}\nHechizo de 1.7 seg\n[q]Seduce al objetivo y le impide toda acción durante un máximo de 30 s. Todo daño elimina el efecto. Solo funciona contra humanoides.\n\nLanzamiento automático:\n Se lanza contra objetivos que aturden, silencian o aterrorizan a su amo.\n\n(Clic derecho para activar)"}
