MultiLanguageSpellData['mx'][133781] = {name = "Contratar mago", additional_info = "Hechizo de 1 seg\n[q]Contrata a un mago que lanza Luminosidad Arcana sobre jugadores de la Alianza cercanos sin coste alguno.\n\nLuminosidad Arcana\n Alcance de 30 m\n Instantáneo\n Requires Mage Infunde luminosidad al objetivo, lo que aumenta su poder con hechizos un 10% y su probabilidad de golpe crítico un 5% durante 1 h. Solo funciona en la Espesura Krasarang."}
MultiLanguageSpellData['mx'][133782] = {name = "Contratar paladín", additional_info = "Hechizo de 1 seg\n[q]Contrata a un paladín que lanza Bendición de poderío sobre jugadores de la Alianza cercanos sin coste alguno.\n\nBendición de poderío\n Alcance de 30 m\n Instantáneo\n Requires Paladin Da a un objetivo amistoso una Bendición que aumenta 3000 p. su maestría. Solo funciona en la Espesura Krasarang."}
MultiLanguageSpellData['mx'][133783] = {name = "Contratar sacerdote", additional_info = "Hechizo de 1 seg\n[q]Contrata a un sacerdote que lanza Palabra de poder: entereza sobre jugadores de la Alianza cercanos sin coste alguno.\n\nPalabra de poder: entereza 4.4% of base mana Alcance de 40 m Instantáneo\n Requires Priest\n Requires level 22 Imbuye de vitalidad al objetivo, lo que aumenta un 10% su aguante durante 1 h. Solo funciona en la Espesura Krasarang."}
MultiLanguageSpellData['mx'][133784] = {name = "Contratar druida", additional_info = "Hechizo de 1 seg\n[q]Contrata a un druida que lanza Marca de lo Salvaje sobre jugadores de la Alianza cercanos sin coste alguno.\n\nMarca de lo Salvaje\n Alcance de 30 m\n Instantáneo\n Requires Druid Aumenta la fuerza, la agilidad y el intelecto del objetivo amistoso un 5% durante 1 h. Solo funciona en la Espesura Krasarang."}
MultiLanguageSpellData['mx'][133785] = {name = "Contratar guerrero", additional_info = "Hechizo de 1 seg\n[q]Contrata a un guerrero que lanza Grito de batalla resonante sobre jugadores de la Alianza cercanos sin coste alguno.\n\nGrito de batalla resonante\n Alcance de 30 m\n Instantáneo\n Requires Warrior Aumenta un 10% el poder de ataque del objetivo. Solo funciona en la Espesura Krasarang."}
MultiLanguageSpellData['mx'][133786] = {name = "Contratar pícaro", additional_info = "Hechizo de 1 seg\n[q]Contrata a un pícaro que lanza Gesto de hoja presta sobre jugadores de la Alianza cercanos sin coste alguno.\n\nGesto de hoja presta\n Alcance de 30 m\n Instantáneo\n Requires Rogue Aumenta un 10% la velocidad de ataque cuerpo a cuerpo y a distancia del objetivo. Solo funciona en la Espesura Krasarang."}
MultiLanguageSpellData['mx'][133787] = {name = "Contratar chamán", additional_info = "Hechizo de 1 seg\n[q]Contrata a un chamán que lanza Juramento elemental vinculante sobre jugadores de la Alianza cercanos sin coste alguno.\n\nJuramento elemental vinculante\n Alcance de 30 m\n Instantáneo\n Requires Shaman\n Requires level 55 Otorga un 5% de celeridad con hechizos al objetivo. Solo funciona en la Espesura Krasarang."}
