MultiLanguageSpellData['mx'][139771] = {name = "Latigazo de relámpagos", additional_info = "Rango ilimitado\nHechizo de 2 seg\n[q]Golpea al enemigo con una Descarga de relámpagos que se extiende a otro enemigo cercano. Afecta a un máximo de 5 objetivos e inflige mayor daño de Naturaleza a cada objetivo sucesivo."}
