MultiLanguageSpellData['mx'][139773] = {name = "Estandarte del imperio mántide", additional_info = "Hechizo de 2 seg\n[q]A pesar de la poderosa magia que controlaban, a menudo los mogu preferían utilizar esclavos para que construyeran sus enormes monumentos. Este libro detalla el coste, en esclavos, de la construcción de uno de tales monumentos."}
