MultiLanguageSpellData['mx'][145415] = {name = "Mutilar", additional_info = "{55 p. de energía} {Alcance de ataques cuerpo a cuerpo}\nInstante\n[q]Ataque instantáneo con ambas armas que inflige un 280 % de daño con arma más 312 p. extra con cada arma. Otorga 0 p. de combo."}
MultiLanguageSpellData['mx'][145416] = {name = "Envenenar", additional_info = "{35 p. de energía} {Alcance de ataques cuerpo a cuerpo}\nInstante\n[q]Remate que inflige daño de Naturaleza instantáneo proporcional a la cantidad de puntos de combo en el objetivo. Tras el ataque Envenenar, tu probabilidad de aplicar un veneno aumenta un 15% durante 1 s más 1 s extra por cada punto de combo."}
