MultiLanguageSpellData['mx'][145418] = {name = "Hacer picadillo", additional_info = "{25 p. de energía} {Alcance de 100 m}\nInstante\n[q]Remate que consume los puntos de combo en cualquier objetivo cercano para aumentar la velocidad de ataque cuerpo a cuerpo un 40%. Se prolonga por cada punto de combo."}
MultiLanguageSpellData['mx'][145419] = {name = "Veneno mortal", additional_info = "Alcance de 100 m\nInstante\n[q]Las armas envenenadas tienen una probabilidad de infligir 9250 to 10750 p. de daño de Naturaleza a un objetivo que ya esté afectado por Veneno mortal."}
MultiLanguageSpellData['mx'][145420] = {name = "Veneno mortal", additional_info = "Alcance de 100 m\nInstante\n[q]Cubre tus armas con un veneno letal que dura 1 h. Cada golpe tiene un 30% de probabilidad de envenenar al enemigo e infligir ( 748 * 4) p. de daño de Naturaleza durante 12 s. Las siguientes aplicaciones del veneno infligirán 390 p. de daño de Naturaleza de forma instantánea."}
MultiLanguageSpellData['mx'][145421] = {name = "Veneno mortal", additional_info = "Hechizo de 3 seg\nRequiere Arma cuerpo a cuerpo de una mano\n[q]Cubre tus armas con un veneno letal que dura 12 s. Cada golpe tiene un 30% de probabilidad de envenenar al enemigo e infligir 80000 p. de daño de Naturaleza durante 12 s. Las siguientes aplicaciones del veneno infligirán 9250 to 10750 p. de daño de Naturaleza de forma instantánea.\n(Probabilidad de que accione: 30%)"}
MultiLanguageSpellData['mx'][145422] = {name = "Abanico de cuchillos", additional_info = "35 p. de energía\nInstante\n[q]Giras instantáneamente desatando una lluvia de cuchillos que se lanzan a todos los objetivos en un radio de 10 m e infligen 46250 to 53750 p. de daño físico. Este ataque tiene una probabilidad de aplicar tus venenos activos al índice habitual. Otorga 46250 to 53750 p. de combo si golpea a tu objetivo de combo actual."}
MultiLanguageSpellData['mx'][145423] = {name = "Sigilo", additional_info = "{Instante} {6 seg de reutilización}\n[q]Te oculta entre las sombras, lo que te permite acechar a enemigos sin ser visto. Dura hasta que se cancela."}
