MultiLanguageSpellData['mx'][145426] = {name = "Paso de las Sombras", additional_info = "Alcance de 25 m\n{Instante} {24 seg de reutilización}\n[q]Provoca que des un paso en las sombras y reaparezcas detrás de un objetivo. Tu velocidad de movimiento aumenta un 70% durante los 2 s siguientes."}
MultiLanguageSpellData['mx'][145427] = {name = "Patada", additional_info = "Alcance de ataques cuerpo a cuerpo\n{Instante} {15 seg de reutilización}\n[q]Una patada rápida que interrumpe el lanzamiento de hechizos y evita que se puedan lanzar hechizos de esa misma escuela durante 2 s."}
