MultiLanguageSpellData['mx'][145433] = {name = "Carga Arcana", additional_info = "Instante\n[q]Carga Arcana que se genera con Explosión Arcana, Misiles Arcanos y Deflagración Arcana, y se consume con Tromba Arcana y Evocación:\n\n Explosión Arcana\n\n Genera una carga.\n El daño de Explosión Arcana aumenta un 50% por carga y su coste de maná aumenta un 150% por carga.\n\n Misiles Arcanos\n Genera una carga.\n El daño de Misiles Arcanos aumenta un 50% por carga.\n\n Deflagración Arcana\n Reinicia la duración de las cargas y tiene un 30 % de probabilidad de generar una carga si se golpea al menos a un objetivo.\n\n Tromba Arcana\n Consume todas las cargas.\n El daño de Tromba Arcana aumenta un 50% por carga y golpea a 1 objetivo cercano extra por carga con un 50 % del daño.\n\n Evocación\n Consume todas las cargas.\n La regeneración de maná de Evocación aumenta un 25% por carga.\n\n Se acumula hasta 4 veces y dura 10 s."}
MultiLanguageSpellData['mx'][145434] = {name = "Explosión Arcana", additional_info = "{8% del maná base} {Alcance de 40 m}\nHechizo de 2 seg\n[q]Golpea al objetivo con energía, lo que inflige 809 p. de daño Arcano. Genera una carga Arcana.\n\n El daño de Explosión Arcana aumenta un 50% por carga Arcana y su coste de maná aumenta un 150% por carga Arcana."}
MultiLanguageSpellData['mx'][145435] = {name = "Misiles Arcanos", additional_info = "Alcance de 60 m\nCanalizado\n[q]Lanza contra el enemigo cinco oleadas de Misiles Arcanos durante 2 s, lo que inflige 231 p. de daño Arcano por oleada. Genera una carga Arcana.\n\n El daño de Misiles Arcanos aumenta un 50% por carga Arcana.\n\n Cada hechizo dañino que lances tiene la probabilidad de activar Misiles Arcanos. Límite de 2 cargas."}
MultiLanguageSpellData['mx'][145436] = {name = "Misiles Arcanos", additional_info = "Alcance de 40 m\nCanalizado (Hechizo de 2 seg)\n[q]Lanza contra el enemigo cinco oleadas de Misiles Arcanos durante 2 s, lo que inflige 231 p. de daño Arcano por oleada. Genera una carga Arcana.\n\n El daño de Misiles Arcanos aumenta un 50% por carga Arcana."}
MultiLanguageSpellData['mx'][145437] = {name = "Tromba Arcana", additional_info = "{4% del maná base} {Alcance de 40 m}\n{Instante} {3 seg de reutilización}\n[q]Lanza descargas de energía Arcana contra el objetivo enemigo, lo que inflige 50000 p. de daño Arcano. También inflige un 50 % de daño a 4 objetivos cercanos extra. Consume todas las cargas Arcanas.\n\n El daño de Tromba Arcana aumenta un 50% por carga Arcana."}
