MultiLanguageSpellData['mx'][148255] = {name = "Glifo de Muerte presta", additional_info = "Hechizo de 3 seg 3\nHerramientas: Juego de caligrafía de virtuoso\nComponentes:\nPapiro ligero , Tinta onírica (3)\n[q9]Glifo Sublime\nClases: Caballero de la muerte\nNecesitas ser de nivel 25\n[q2]Uso: Te enseña permanentemente este glifo.\n\nEl efecto de celeridad de Segador de almas ahora también aumenta tu velocidad de movimiento un 30% mientras dura."}
