MultiLanguageSpellData['mx'][1247279] = {name = "Brebaje de ojo de tigre", additional_info = "Instante\n[q]Por cada 3 p. de chi que consumes con tus habilidades y ataques, obtienes una carga de Brebaje de ojo de tigre. Usa Brebaje de ojo de tigre para consumir las cargas y obtener un [ 0 * (( 90 > 79 ? 1 : 0)) + 3.5]% más de daño durante 15 s.\n\n Brebaje de ojo de tigre puede acumularse un máximo de 20 veces, pero solo se puede consumir un máximo de 10 acumulaciones a la vez para infligir un [( 0 * (( 90 > 79 ? 1 : 0)) + 3.5) * 10 ]% más de daño."}
MultiLanguageSpellData['mx'][1247280] = {name = "Maestría: Furia embotellada", additional_info = "[q]Fuera de campos de batalla y arenas:\n Otorga un [ 0 * (( 90 > 79 ? 1 : 0)) + 3.5]% más de daño por acumulación de Brebaje de ojo de tigre.\n\n Dentro de campos de batalla y arenas:\n Cuando generas cargas de Brebaje de ojo de tigre, tienes un 20% de probabilidad de generar una carga más."}
